const LOGO = 'data:image/png;base64,';
'use strict';
/* Clinica Pazienti – versione web installabile (iPhone / Android / PC).
   Stesso database, stessi utenti e stessi permessi dell'app Android. */

const CFG = window.CONFIG;
const sb = window.supabase.createClient(CFG.SUPABASE_URL, CFG.SUPABASE_ANON_KEY, {
  auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: false }
});
const DOMINIO = 'clinica.local';
const MODULI = [
  ['pazienti', 'Anagrafica pazienti'], ['clinica', 'Anamnesi e note cliniche'], ['foto', 'Foto prima/dopo'],
  ['agenda', 'Agenda'], ['listino', 'Listino'], ['conti', 'Preventivi e pagamenti'], ['magazzino', 'Magazzino e impianti'], ['eliminazione', 'Eliminare dati']
];

/* ---------- utilità ---------- */
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const euro = v => new Intl.NumberFormat('it-IT', { style: 'currency', currency: 'EUR' }).format(+v || 0);
const num = s => parseFloat(String(s ?? '').trim().replace(',', '.')) || 0;
const pad = n => String(n).padStart(2, '0');
const fData = d => d ? new Date(String(d).length === 10 ? d + 'T00:00:00' : d).toLocaleDateString('it-IT') : '';
const fDataOra = d => d ? new Date(d).toLocaleString('it-IT', { dateStyle: 'short', timeStyle: 'short' }) : '';
const oggiISO = () => { const d = new Date(); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`; };
const isoData = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const isoOra = d => `${pad(d.getHours())}:${pad(d.getMinutes())}`;
const fobj = f => Object.fromEntries(new FormData(f));

let me = null;
const S = { pazienti: [], appuntamenti: [], listino: [], utenti: [] };

const can = (m, edit = false) => {
  if (!me || !me.attivo) return false;
  if (me.ruolo === 'admin') return true;
  const v = (me.permessi || {})[m] || 'none';
  return edit ? v === 'edit' : (v === 'view' || v === 'edit');
};

/* esegue una chiamata Supabase e lancia un errore leggibile */
async function q(p) {
  const { data, error } = await p;
  if (error) {
    const m = error.message || String(error);
    if (/row-level security|permission denied/i.test(m)) throw new Error('Non hai il permesso per questa operazione.');
    throw new Error(m);
  }
  return data;
}
const log = (azione, dettaglio = '') => { sb.from('registro').insert({ azione, dettaglio }).then(() => {}, () => {}); };

let occupato = 0;
function busy(on) { occupato += on ? 1 : -1; $('#busy').hidden = occupato <= 0; }
async function ok(fn) {
  busy(true);
  try { return await fn(); }
  catch (e) { avviso('Attenzione', e.message || String(e)); }
  finally { busy(false); }
}

function modal(html, wide = false) {
  const m = $('#modal');
  m.innerHTML = `<div class="box${wide ? ' wide' : ''}">${html}</div>`;
  m.hidden = false;
  m.onclick = e => { if (e.target === m) chiudi(); };
}
function chiudi() { $('#modal').hidden = true; $('#modal').innerHTML = ''; }
function avviso(t, msg) {
  modal(`<h2>${esc(t)}</h2><p>${esc(msg)}</p><div class="row"><button class="b" id="mk">OK</button></div>`);
  $('#mk').onclick = chiudi;
}
function conferma(t, msg, onOk) {
  modal(`<h2>${esc(t)}</h2><p>${esc(msg)}</p><div class="row"><button class="b d" id="mok">Conferma</button><button class="b o" id="mno">Annulla</button></div>`);
  $('#mno').onclick = chiudi;
  $('#mok').onclick = () => { chiudi(); onOk(); };
}

const go = h => { location.hash = h; };
function indietro() { if (history.length > 1) history.back(); else go('#/pazienti'); }

/* ---------- componenti HTML ---------- */
const campo = (et, nome, val = '', tipo = 'text', extra = '') =>
  `<label class="f">${esc(et)}<input type="${tipo}" name="${nome}" value="${esc(val)}" ${extra}></label>`;
const area = (et, nome, val = '') => `<label class="f">${esc(et)}<textarea name="${nome}">${esc(val)}</textarea></label>`;
const scelta = (nome, opzioni, sel) =>
  `<div class="chips">${opzioni.map(o => `<label><input type="radio" name="${nome}" value="${esc(o)}" ${o === sel ? 'checked' : ''}>${esc(o)}</label>`).join('')}</div>`;
const numWa = t => { let n = String(t || '').replace(/[^\d+]/g, ''); if (n.startsWith('00')) return n.slice(2); if (n.startsWith('+')) return n.slice(1); return n ? '39' + n.replace(/^0+(?=3)/, '') : ''; };
const inizPaz = p => `${(p.cognome || '')[0] || ''}${(p.nome || '')[0] || ''}`.toUpperCase();
const medicoBreve = m => (m.includes('Delia') && m.includes('Micieli')) ? 'Entrambi' : m;
const kv = (e, v) => `<div class="kv"><span>${esc(e)}</span><span>${v}</span></div>`;

const NAV_MAP = { pazienti: 'pazienti', paziente: 'pazienti', pform: 'pazienti', rel: 'pazienti', prev: 'pazienti', impianto: 'pazienti', anam: 'pazienti', cons: 'pazienti', istr: 'pazienti', firma: 'pazienti', app: 'agenda', agenda: 'agenda', chat: 'chat', conv: 'chat', magazzino: 'magazzino', articolo: 'magazzino', listino: 'listino', voce: 'listino', utenti: 'utenti', utente: 'utenti' };
const navDaRotta = () => NAV_MAP[(location.hash.replace(/^#\//, '') || 'pazienti').split('/')[0]] || 'pazienti';
function schermo({ titolo, back = false, azioni = '', nav = null, body }) {
  nav = nav || navDaRotta();
  const navi = nav ? `<nav class="bar"><div>
    <a href="#/pazienti" class="${nav === 'pazienti' ? 'on' : ''}"><b><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="9" cy="8" r="3.5"/><path d="M2.5 20c.6-3.4 3-5.5 6.5-5.5s5.9 2.1 6.5 5.5"/><path d="M16 4.8a3.4 3.4 0 010 6.4M18.5 14.8c1.8.7 2.8 2.3 3 4.7"/></svg></b>Pazienti</a>
    ${can('agenda') ? `<a href="#/agenda" class="${nav === 'agenda' ? 'on' : ''}"><b><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3.5" y="5" width="17" height="15" rx="2.5"/><path d="M3.5 10h17M8 3v4M16 3v4"/></svg></b>Agenda</a>` : ''}
    <a href="#/chat" class="${nav === 'chat' ? 'on' : ''}"><b><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 5h16v11H9l-5 4z"/><path d="M8 10h8M8 13h5"/></svg><i class="chbd" hidden></i></b>Chat</a>
    ${can('magazzino') ? `<a href="#/magazzino" class="${nav === 'magazzino' ? 'on' : ''}"><b><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3.5 8.5L12 4l8.5 4.5v8L12 21l-8.5-4.5z"/><path d="M3.5 8.5L12 13l8.5-4.5M12 13v8"/></svg></b>Magazzino</a>` : ''}
    ${can('listino') ? `<a href="#/listino" class="${nav === 'listino' ? 'on' : ''}"><b><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="6" width="18" height="12" rx="2.5"/><circle cx="12" cy="12" r="2.6"/></svg></b>Listino</a>` : ''}
    ${me.ruolo === 'admin' ? `<a href="#/utenti" class="${nav === 'utenti' ? 'on' : ''}"><b><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="8" cy="15" r="4"/><path d="M11 12l9-9M16 7l3 3M14 9l2 2"/></svg></b>Utenti</a>` : ''}
    <button id="esci"><b style="display:block"><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10 4H6a2 2 0 00-2 2v12a2 2 0 002 2h4M15 8l4 4-4 4M19 12H9"/></svg></b>Esci</button></div></nav>` : '';
  $('#app').innerHTML = `<header class="top">${back ? '<button class="ic" id="bk" aria-label="Indietro">←</button>' : '<img class="logo" src="' + LOGO + '" alt="">'}
    <h1>${esc(titolo)}</h1><div>${azioni}</div></header><main>${body}</main>${navi}`;
  if (back) $('#bk').onclick = indietro;
  if (typeof aggiornaBadge === 'function') aggiornaBadge();
  const e = $('#esci'); if (e) e.onclick = () => conferma('Uscire?', 'Dovrai rifare l\'accesso.', esci);
  window.scrollTo(0, 0);
}

/* ---------- accesso ---------- */
function vistaLogin(msg = '') {
  $('#app').innerHTML = `<div class="login"><img src="${LOGO}" alt=""><h1>PROAESTHETICS</h1><p class="sub">Chirurgia plastica ed estetica</p><div class="gl"></div>
    <form id="lf" autocomplete="on">
      <label class="f">Nome utente<input name="u" autocomplete="username" autocapitalize="none" autocorrect="off" required></label>
      <label class="f">Password<input name="p" type="password" autocomplete="current-password" required></label>
      <div class="err" id="le">${esc(msg)}</div>
      <button class="b" style="width:100%;margin-top:6px">Accedi</button></form><p class="m" style="margin-top:28px">Accesso riservato al personale autorizzato.<br>I dati dei pazienti sono protetti.<br><small>v16</small></p></div>`;
  $('#lf').onsubmit = async e => {
    e.preventDefault();
    const d = fobj(e.target);
    busy(true);
    try {
      const { error } = await sb.auth.signInWithPassword({ email: `${d.u.trim().toLowerCase()}@${DOMINIO}`, password: d.p });
      if (error) throw new Error(/invalid login/i.test(error.message) ? 'Nome utente o password errati.' : error.message);
      await entra();
    } catch (err) { $('#le').textContent = err.message; }
    finally { busy(false); }
  };
}

async function entra() {
  const { data: { session } } = await sb.auth.getSession();
  if (!session) return vistaLogin();
  const p = await q(sb.from('profiles').select('*').eq('id', session.user.id).maybeSingle());
  if (!p) { await esci(); return vistaLogin('Profilo non trovato: contatta l\'amministratore.'); }
  if (!p.attivo) { await esci(); return vistaLogin('Utenza disattivata. Contatta l\'amministratore.'); }
  me = p;
  await caricaTutto();
  if (!location.hash || location.hash === '#/') location.hash = '#/pazienti';
  render();
}

async function esci() {
  me = null; S.pazienti = []; S.appuntamenti = []; S.listino = []; S.utenti = []; S.chat = { utenti: [], msgs: [], letti: {} };
  try { await sb.auth.signOut(); } catch (_) { /* ignora */ }
  location.hash = '';
  vistaLogin();
}

async function caricaTutto() {
  const job = [];
  job.push(q(sb.from('pazienti').select('*').order('cognome').order('nome')).then(d => S.pazienti = d || []));
  if (can('agenda')) job.push(q(sb.from('appuntamenti').select('*').order('inizio')).then(d => S.appuntamenti = d || []));
  if (can('listino') || can('conti') || can('agenda')) job.push(q(sb.from('listino').select('*').order('categoria').order('nome')).then(d => S.listino = d || []).catch(() => {}));
  if (me.ruolo === 'admin') job.push(q(sb.from('profiles').select('*').order('username')).then(d => S.utenti = d || []));
  job.push(chatCarica().catch(() => { }));
  await Promise.all(job);
}
const nomePaz = id => { const p = S.pazienti.find(x => x.id === id); return p ? `${p.cognome} ${p.nome}`.trim() : '—'; };

/* ---------- router ---------- */
const VISTE = {};
let chatT = null;
async function render() {
  if (!me) return;
  const [nome, ...a] = (location.hash.replace(/^#\//, '') || 'pazienti').split('/').map(decodeURIComponent);
  const v = VISTE[nome] || VISTE.pazienti;
  try { await v(...a); } catch (e) { avviso('Attenzione', e.message || String(e)); }
}
window.addEventListener('hashchange', () => { clearInterval(chatT); chiudi(); render(); });

/* ---------- dettatura vocale (microfono sui campi di testo lungo) ---------- */
const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
function micro(root) {
  if (!SR || !root) return;
  root.querySelectorAll('textarea').forEach(t => {
    const lab = t.closest('label');
    if (t.disabled || t.dataset.mic || !lab) return;
    t.dataset.mic = 1; lab.style.position = 'relative';
    const b = document.createElement('button'); b.type = 'button'; b.className = 'mic'; b.setAttribute('aria-label', 'Detta con la voce');
    b.innerHTML = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0014 0M12 18v3"/></svg>';
    lab.appendChild(b);
    let rec = null, on = false;
    b.onclick = () => {
      if (on) { rec.stop(); return; }
      rec = new SR(); rec.lang = 'it-IT'; rec.continuous = true; rec.interimResults = false;
      rec.onresult = e => {
        let txt = '';
        for (let i = e.resultIndex; i < e.results.length; i++) if (e.results[i].isFinal) txt += e.results[i][0].transcript;
        txt = txt.trim();
        if (txt) { const base = t.value.trimEnd(); t.value = base ? base + ' ' + txt : txt.charAt(0).toUpperCase() + txt.slice(1); t.dispatchEvent(new Event('input', { bubbles: true })); }
      };
      rec.onerror = e => { if (e.error === 'not-allowed' || e.error === 'service-not-allowed') avviso('Microfono', 'Il microfono non è disponibile qui. Consenti l\'accesso al microfono oppure usa il microfono della tastiera del telefono.'); };
      rec.onend = () => { on = false; b.classList.remove('on'); };
      try { rec.start(); on = true; b.classList.add('on'); } catch (e) { }
    };
  });
}

/* ---------- CHAT PRIVATA TRA UTENTI ---------- */
S.chat = { utenti: [], msgs: [], letti: {} };
const tms = d => new Date(d).getTime();
const chatKey = m => m.destinatario == null ? 'studio' : (m.mittente === me.id ? m.destinatario : m.mittente);
const chatNonLetti = k => S.chat.msgs.filter(m => m.mittente !== me.id && chatKey(m) === k && (!S.chat.letti[k] || tms(m.creato_il) > tms(S.chat.letti[k]))).length;
const chatTotNuovi = () => ['studio', ...S.chat.utenti.map(u => u.id)].reduce((s, k) => s + chatNonLetti(k), 0);
function aggiornaBadge() {
  const n = me ? chatTotNuovi() : 0;
  document.querySelectorAll('.chbd').forEach(e => { e.textContent = n > 99 ? '99+' : n; e.hidden = !n; });
}
async function chatCarica() {
  if (!me) return;
  const [u, m, l] = await Promise.all([
    q(sb.rpc('utenti_chat')),
    q(sb.from('chat_messaggi').select('*').order('creato_il', { ascending: false }).limit(500)),
    q(sb.from('chat_letti').select('*'))
  ]);
  S.chat.utenti = (u || []).filter(x => x.id !== me.id);
  S.chat.msgs = (m || []).slice().sort((x, y) => tms(x.creato_il) - tms(y.creato_il));
  S.chat.letti = Object.fromEntries((l || []).map(x => [x.chat, x.ultimo]));
  aggiornaBadge();
}
async function chatLetto(k) {
  if (!chatNonLetti(k)) return;
  const ora = new Date().toISOString();
  S.chat.letti[k] = ora; aggiornaBadge();
  try { await q(sb.from('chat_letti').upsert({ user_id: me.id, chat: k, ultimo: ora })); } catch (_) { }
}
setInterval(() => { if (me && !document.hidden) chatCarica().catch(() => { }); }, 20000);
const oraMsg = d => new Date(d).toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' });
const nomeUt = u => (u.nome || u.username || '').trim();
const inizUt = u => nomeUt(u).split(/\s+/).filter(Boolean).slice(0, 2).map(x => x[0].toUpperCase()).join('');

VISTE.chat = async () => {
  schermo({ titolo: 'Chat', nav: 'chat', body: '<div class="lock">🔒 Conversazioni private tra gli utenti dello studio</div><div id="cl"></div>' });
  const disegna = () => {
    const riga = (k, nome, ini, cls) => {
      const ms = S.chat.msgs.filter(m => chatKey(m) === k), ult = ms[ms.length - 1], nn = chatNonLetti(k);
      return `<a class="crow" href="#/conv/${esc(k)}"><span class="av ${cls}">${esc(ini)}</span><span class="g"><b>${esc(nome)}</b><small>${ult ? esc((ult.mittente === me.id ? 'Tu: ' : (k === 'studio' ? (ult.mittente_nome || '') + ': ' : '')) + ult.testo) : 'Nessun messaggio'}</small></span>
        <span class="ct">${ult ? esc(oraMsg(ult.creato_il)) : ''}${nn ? `<br><span class="n">${nn}</span>` : ''}</span></a>`;
    };
    $('#cl').innerHTML = `<div class="over">Gruppo</div>${riga('studio', 'Studio', 'S', 'k')}<div class="over">Messaggi privati</div>` +
      (S.chat.utenti.length ? S.chat.utenti.map(u => riga(u.id, nomeUt(u), inizUt(u), '')).join('') : '<p class="m">Nessun altro utente.</p>');
  };
  disegna();
  try { await chatCarica(); disegna(); } catch (e) { $('#cl').insertAdjacentHTML('afterbegin', '<p class="warn">Chat non disponibile: esegui l\'aggiornamento del database (chat). ' + esc(e.message) + '</p>'); }
};

VISTE.conv = async k => {
  clearInterval(chatT);
  if (!S.chat.utenti.length && k !== 'studio') { try { await chatCarica(); } catch (_) { } }
  const ut = S.chat.utenti.find(u => u.id === k);
  const nome = k === 'studio' ? 'Studio' : ut ? nomeUt(ut) : 'Chat';
  schermo({
    titolo: nome, back: true, azioni: (k !== 'studio' || me.ruolo === 'admin') ? '<button class="t" id="svuota">Svuota</button>' : '',
    body: `<div class="lock">🔒 ${k === 'studio' ? 'Gruppo Studio: lo leggono tutti gli utenti' : 'Solo tu e ' + esc(nome) + ' potete leggere questa chat'}</div>
    <div id="cm" class="chatl"></div>
    <form id="cf" class="cbar"><label class="cin"><textarea name="t" rows="1" placeholder="Scrivi un messaggio…"></textarea></label><button class="snd" aria-label="Invia">➤</button></form>`
  });
  micro($('#cf'));
  let nPrima = -1;
  const disegna = () => {
    const ms = S.chat.msgs.filter(m => chatKey(m) === k);
    let giorno = '', h = '';
    ms.forEach(m => {
      const g = new Date(m.creato_il).toLocaleDateString('it-IT', { weekday: 'long', day: 'numeric', month: 'long' });
      if (g !== giorno) { giorno = g; h += `<div class="day">${esc(g === new Date().toLocaleDateString('it-IT', { weekday: 'long', day: 'numeric', month: 'long' }) ? 'Oggi' : g)}</div>`; }
      const mio = m.mittente === me.id;
      h += `<div class="msg ${mio ? 'out' : 'in'}"${mio ? ` data-id="${esc(m.id)}"` : ''}>${!mio && (k === 'studio' || true) ? `<small>${esc(m.mittente_nome || '')}</small>` : ''}${esc(m.testo).replace(/\n/g, '<br>')}<span class="o">${esc(oraMsg(m.creato_il))}</span></div>`;
    });
    $('#cm').innerHTML = h || '<p class="m" style="text-align:center">Nessun messaggio. Scrivi il primo.</p>';
    if (ms.length !== nPrima) { nPrima = ms.length; window.scrollTo(0, document.body.scrollHeight); }
    document.querySelectorAll('.msg.out[data-id]').forEach(el => el.onclick = () => conferma('Eliminare il messaggio?', 'Sparisce per tutti. Non si può annullare.', () => {
      q(sb.from('chat_messaggi').delete().eq('id', el.dataset.id)).then(() => chatCarica()).then(disegna).catch(e => avviso('Attenzione', e.message || String(e)));
    }));
    chatLetto(k);
  };
  disegna();
  const ta = $('#cf textarea');
  const invia = () => {
    const t = ta.value.trim(); if (!t) return; ta.value = '';
    q(sb.from('chat_messaggi').insert({ mittente: me.id, mittente_nome: me.nome || me.username, destinatario: k === 'studio' ? null : k, testo: t }))
      .then(() => chatCarica()).then(disegna).catch(e => { ta.value = t; avviso('Attenzione', e.message || String(e)); });
  };
  $('#cf').onsubmit = e => { e.preventDefault(); invia(); };
  ta.onkeydown = e => { if (e.key === 'Enter' && !e.shiftKey && window.innerWidth > 700) { e.preventDefault(); invia(); } };
  const sv = $('#svuota');
  if (sv) sv.onclick = () => conferma('Svuotare la chat?', k === 'studio' ? 'Tutti i messaggi del gruppo verranno eliminati per tutti.' : 'Tutti i messaggi con ' + nome + ' verranno eliminati per entrambi. Non si può annullare.', () => {
    const dels = k === 'studio' ? [sb.from('chat_messaggi').delete().is('destinatario', null)]
      : [sb.from('chat_messaggi').delete().eq('mittente', me.id).eq('destinatario', k), sb.from('chat_messaggi').delete().eq('mittente', k).eq('destinatario', me.id)];
    Promise.all(dels.map(d => q(d))).then(() => chatCarica()).then(disegna).catch(e => avviso('Attenzione', e.message || String(e)));
  });
  chatT = setInterval(() => { chatCarica().then(disegna).catch(() => { }); }, 3000);
};

/* ---------- PAZIENTI ---------- */
VISTE.pazienti = async () => {
  schermo({
    titolo: 'Pazienti', nav: 'pazienti',
    body: `<input id="cerca" type="search" placeholder="Cerca per nome o telefono" style="margin:0 0 6px">
      <div class="chips" style="margin:0 0 6px"><label><input type="radio" name="ord" value="alfa" checked>Alfabetico</label><label><input type="radio" name="ord" value="ins">Ordine di inserimento</label></div><div class="list" id="lista"></div>
      ${can('pazienti', true) ? '<button class="fab" id="nuovo" aria-label="Nuovo paziente">+</button>' : ''}`
  });
  const disegna = () => {
    const t = $('#cerca').value.trim().toLowerCase();
    const ins = document.querySelector('input[name=ord]:checked').value === 'ins';
    const l = S.pazienti.filter(p => !t || `${p.cognome} ${p.nome} ${p.telefono || ''}`.toLowerCase().includes(t))
      .sort(ins ? (a, b) => String(b.creato_il || '').localeCompare(String(a.creato_il || '')) : (a, b) => `${a.cognome} ${a.nome}`.localeCompare(`${b.cognome} ${b.nome}`, 'it'));
    let prec = '';
    $('#lista').innerHTML = l.length ? l.map(p => {
      const lt = (p.cognome || '?')[0].toUpperCase(), testa = !ins && lt !== prec ? `<div class="lt">${esc(lt)}</div>` : ''; prec = lt;
      const med = p.medici ? `<span class="tag">${esc(medicoBreve(p.medici))}</span>` : '';
      return `${testa}<a class="it pz" href="#/paziente/${p.id}"><span class="av">${esc(inizPaz(p))}</span><span class="g"><b>${esc(p.cognome)} ${esc(p.nome)}</b><br><small>${esc(p.telefono || '')}</small></span>${med}</a>`;
    }).join('') : '<p class="m">Nessun paziente</p>';
  };
  $('#cerca').oninput = disegna;
  document.querySelectorAll('input[name=ord]').forEach(r => r.onchange = disegna); disegna();
  if ($('#nuovo')) $('#nuovo').onclick = () => go('#/pform/new');
};

VISTE.pform = async id => {
  const nuovo = id === 'new';
  const p = nuovo ? {} : S.pazienti.find(x => x.id === id) || {};
  schermo({
    titolo: nuovo ? 'Nuovo paziente' : 'Modifica paziente', back: true,
    body: `<form id="f">
      ${campo('Cognome', 'cognome', p.cognome, 'text', 'required')}${campo('Nome', 'nome', p.nome, 'text', 'required')}
      ${campo('Data di nascita', 'data_nascita', p.data_nascita || '', 'date')}${campo('Luogo di nascita', 'luogo_nascita', p.luogo_nascita)}
      <label class="f">Sesso${scelta('sesso', ['F', 'M', 'Altro'], p.sesso || '')}</label>
      ${campo('Codice fiscale', 'codice_fiscale', p.codice_fiscale, 'text', 'autocapitalize="characters"')}
      ${campo('Cellulare', 'telefono', p.telefono, 'tel')}${campo('Telefono fisso (domicilio)', 'telefono_fisso', p.telefono_fisso, 'tel')}${campo('Email', 'email', p.email, 'email')}${campo('Indirizzo', 'indirizzo', p.indirizzo)}
      <div class="grid2">${campo('Stato civile', 'stato_civile', p.stato_civile, 'text', 'list="stciv"')}${campo('Professione', 'professione', p.professione)}</div>
      <datalist id="stciv"><option>Celibe/Nubile</option><option>Coniugato/a</option><option>Convivente</option><option>Separato/a</option><option>Divorziato/a</option><option>Vedovo/a</option></datalist>
      <div class="grid2">${campo('N° registro', 'n_reg', p.n_reg)}${campo('Data e ora ricovero', 'data_ricovero', dtLocal(p.data_ricovero), 'datetime-local')}</div>
      <div class="f" style="margin-top:12px">Medico</div>
      <label class="chk" style="margin:6px 0"><input type="checkbox" name="m_delia" ${haMed(p.medici, 'Delia') ? 'checked' : ''}>Prof. Gabriele Delia</label>
      <label class="chk" style="margin:6px 0"><input type="checkbox" name="m_micieli" ${haMed(p.medici, 'Micieli') ? 'checked' : ''}>Dott. Pietro Micieli</label>
      <label class="chk"><input type="checkbox" name="consenso_privacy" ${p.consenso_privacy ? 'checked' : ''}>Informativa privacy (GDPR) firmata</label>
      <label class="chk"><input type="checkbox" name="consenso_informato" ${p.consenso_informato ? 'checked' : ''}>Consenso informato firmato</label>
      ${campo('Data del consenso', 'consenso_data', p.consenso_data || '', 'date')}
      <div class="row"><button class="b">Salva</button></div></form>`
  });
  $('#f').onsubmit = e => {
    e.preventDefault();
    const d = fobj(e.target);
    const rec = {
      nome: d.nome.trim(), cognome: d.cognome.trim(), data_nascita: d.data_nascita || null, sesso: d.sesso || '',
      codice_fiscale: (d.codice_fiscale || '').trim().toUpperCase(), telefono: (d.telefono || '').trim(), email: (d.email || '').trim(),
      indirizzo: (d.indirizzo || '').trim(), luogo_nascita: (d.luogo_nascita || '').trim(), telefono_fisso: (d.telefono_fisso || '').trim(), stato_civile: (d.stato_civile || '').trim(), professione: (d.professione || '').trim(), n_reg: (d.n_reg || '').trim(), data_ricovero: d.data_ricovero ? new Date(d.data_ricovero).toISOString() : null, medici: [d.m_delia ? 'Prof. Gabriele Delia' : '', d.m_micieli ? 'Dott. Pietro Micieli' : ''].filter(Boolean).join(', '),
      consenso_privacy: !!d.consenso_privacy, consenso_informato: !!d.consenso_informato,
      consenso_data: d.consenso_informato ? (d.consenso_data || oggiISO()) : (d.consenso_data || null)
    };
    ok(async () => {
      let pid = id;
      if (nuovo) { const r = await q(sb.from('pazienti').insert(rec).select().single()); pid = r.id; log('crea_paziente', pid); }
      else { await q(sb.from('pazienti').update(rec).eq('id', id)); log('modifica_paziente', id); }
      S.pazienti = await q(sb.from('pazienti').select('*').order('cognome').order('nome'));
      history.replaceState(null, '', `#/paziente/${pid}`); render();
    });
  };
};

VISTE.paziente = async (id, tab = 'scheda') => {
  const pz = S.pazienti.find(x => x.id === id);
  if (!pz) return schermo({ titolo: 'Paziente', back: true, body: '<p>Paziente non trovato</p>' });
  const tabs = [['scheda', 'Scheda']];
  if (can('clinica')) tabs.push(['clinica', 'Clinica']);
  if (can('clinica')) tabs.push(['documenti', 'Documenti']);
  if (can('foto')) tabs.push(['foto', 'Foto']);
  if (can('conti')) tabs.push(['conti', 'Conti']);
  if (can('magazzino')) tabs.push(['impianti', 'Impianti']);
  if (me.ruolo === 'admin') tabs.push(['storico', 'Storico']);
  if (!tabs.some(t => t[0] === tab)) tab = 'scheda';
  schermo({
    titolo: 'Paziente', back: true, azioni: '<button class="t" id="pdf">PDF / Stampa</button>',
    body: `<div class="phd"><span class="av big">${esc(inizPaz(pz))}</span><div><div class="nm">${esc(pz.cognome)} ${esc(pz.nome)}</div><small class="m">${esc(pz.telefono || '')}</small></div></div>
      <div class="qa">${pz.telefono ? `<a class="b o" href="tel:${esc(pz.telefono)}">Chiama</a><a class="b o" target="_blank" rel="noopener" href="https://wa.me/${numWa(pz.telefono)}">WhatsApp</a>` : ''}${can('agenda', true) ? `<a class="b" href="#/app/new/${id}">Fissa</a>` : ''}</div>
      ${tabs.length > 1 ? `<div class="tabs">${tabs.map(t => `<a class="${t[0] === tab ? 'on' : ''}" href="#/paziente/${id}/${t[0]}" replace>${t[1]}</a>`).join('')}</div>` : ''}<div id="tc"></div>`
  });
  $('#pdf').onclick = () => ok(() => stampa(id));
  log('apri_paziente', id);
  await ({ scheda: tabScheda, clinica: tabClinica, documenti: tabDocumenti, foto: tabFoto, conti: tabConti, impianti: tabImpianti, storico: tabStorico }[tab])(pz);
};

const STO_T = { pazienti: 'anagrafica', anamnesi: 'anamnesi', note_cliniche: 'nota clinica', foto: 'foto', appuntamenti: 'appuntamento', preventivi: 'preventivo', pagamenti: 'pagamento', relazioni: 'relazione', consensi: 'consenso informato', istruzioni_postop: 'istruzioni post-operatorie', mag_articoli: 'articolo', impianti: 'impianto' };
const STO_A = { insert: 'ha creato', update: 'ha modificato', delete: 'ha eliminato' };
async function tabStorico(pz) {
  $('#tc').innerHTML = '<p class="m">Caricamento…</p>';
  let l = [];
  try { l = await q(sb.from('storico').select('*').eq('paziente_id', pz.id).order('creato_il', { ascending: false }).limit(300)); }
  catch (e) { $('#tc').innerHTML = '<p class="warn">Storico non disponibile: esegui l\'aggiornamento del database. ' + esc(e.message) + '</p>'; return; }
  const adm = me.ruolo === 'admin';
  $('#tc').innerHTML = `<p class="m" style="font-size:12px">🔒 Visibile e cancellabile solo dall'amministratore.</p>` + (l.length ? l.map(x => {
    const d = new Date(x.creato_il);
    return `<div class="sto"><div class="sd">${esc(d.toLocaleDateString('it-IT'))}<br>${esc(oraMsg(x.creato_il))}</div><div style="flex:1"><b>${esc(x.utente_nome || 'Utente')}</b> ${esc(STO_A[x.azione] || x.azione)} ${esc(STO_T[x.tabella] || x.tabella)}${x.dettaglio ? `<small>${esc(x.dettaglio.replace(/_/g, ' '))}</small>` : ''}</div>${adm ? `<button class="t d" data-sd="${x.id}" aria-label="Elimina">✕</button>` : ''}</div>`;
  }).join('') + (adm ? '<div class="row"><button class="b d" id="sdall">Cancella tutto lo storico</button></div>' : '') : '<p class="m">Nessuna modifica registrata.</p>');
  if (!adm) return;
  document.querySelectorAll('[data-sd]').forEach(b => b.onclick = () => conferma('Eliminare la voce?', 'La voce dello storico verrà cancellata definitivamente.', () => ok(async () => {
    await q(sb.from('storico').delete().eq('id', b.dataset.sd)); await tabStorico(pz);
  })));
  const all = $('#sdall');
  if (all) all.onclick = () => conferma('Cancellare tutto lo storico?', 'Verranno cancellate tutte le voci di questo paziente. Non si può annullare.', () => ok(async () => {
    await q(sb.from('storico').delete().eq('paziente_id', pz.id)); await tabStorico(pz);
  }));
}

function tabScheda(pz) {
  $('#tc').innerHTML = `${kv('Data di nascita', esc(fData(pz.data_nascita)))}${pz.luogo_nascita ? kv('Luogo di nascita', esc(pz.luogo_nascita)) : ''}${kv('Sesso', esc(pz.sesso))}${kv('Codice fiscale', esc(pz.codice_fiscale))}
    ${kv('Cellulare', pz.telefono ? `<a href="tel:${esc(pz.telefono)}">${esc(pz.telefono)}</a>` : '')}${pz.telefono_fisso ? kv('Telefono fisso', `<a href="tel:${esc(pz.telefono_fisso)}">${esc(pz.telefono_fisso)}</a>`) : ''}${kv('Email', esc(pz.email))}${kv('Indirizzo', esc(pz.indirizzo))}
    ${pz.stato_civile ? kv('Stato civile', esc(pz.stato_civile)) : ''}${pz.professione ? kv('Professione', esc(pz.professione)) : ''}${pz.n_reg ? kv('N° registro', esc(pz.n_reg)) : ''}${pz.data_ricovero ? kv('Ricovero', esc(dataOra(pz.data_ricovero))) : ''}
    ${kv('Medico', esc(pz.medici))}
    ${kv('Privacy (GDPR)', pz.consenso_privacy ? 'Informativa firmata' : '<span class="warn">NON firmata</span>')}
    ${kv('Consenso informato', pz.consenso_informato ? 'Firmato il ' + esc(fData(pz.consenso_data)) : '<span class="warn">NON firmato</span>')}
    <div class="row">
      ${can('pazienti', true) ? `<a class="b o" href="#/pform/${pz.id}">Modifica</a>` : ''}
      ${can('agenda', true) ? `<a class="b o" href="#/app/new/${pz.id}">Appuntamento</a>` : ''}
      ${can('eliminazione', true) ? '<button class="b d" id="del">Elimina paziente</button>' : ''}</div>`;
  const d = $('#del');
  if (d) d.onclick = () => conferma('Eliminare il paziente?', 'Verranno eliminati anche note, foto, preventivi e pagamenti. Non si può annullare.', () => ok(async () => {
    const f = await q(sb.from('foto').select('percorso').eq('paziente_id', pz.id)).catch(() => []);
    if (f.length) await sb.storage.from('foto-pazienti').remove(f.map(x => x.percorso));
    await q(sb.from('pazienti').delete().eq('id', pz.id));
    log('elimina_paziente', pz.id);
    S.pazienti = S.pazienti.filter(x => x.id !== pz.id);
    history.replaceState(null, '', '#/pazienti'); render();
  }));
}

/* ---------- CLINICA ---------- */
async function tabClinica(pz) {
  const id = pz.id, mod = can('clinica', true);
  const [an, note, rels] = await Promise.all([
    q(sb.from('anamnesi').select('*').eq('paziente_id', id)),
    q(sb.from('note_cliniche').select('*').eq('paziente_id', id).order('creato_il', { ascending: false })),
    q(sb.from('relazioni').select('*').eq('paziente_id', id).order('data_relazione', { ascending: false })).catch(() => [])
  ]);
  const a = an[0] || {};
  const dis = mod ? '' : 'disabled';
  $('#tc').innerHTML = `<h3 style="margin-top:0">Anamnesi</h3>
    <form id="fa">${area('Diagnosi', 'diagnosi', a.diagnosi).replace('<textarea', `<textarea ${dis}`)}
      ${area('Tipologia di intervento', 'tipo_intervento', a.tipo_intervento).replace('<textarea', `<textarea ${dis}`)}
      ${area('Allergie', 'allergie', a.allergie).replace('<textarea', `<textarea ${dis}`)}
      ${area('Farmaci in corso', 'farmaci', a.farmaci).replace('<textarea', `<textarea ${dis}`)}
      ${area('Patologie', 'patologie', a.patologie).replace('<textarea', `<textarea ${dis}`)}
      <label class="f">Fumo${scelta('fumatore', ['No', 'Ex', 'Sì'], a.fumatore || '')}</label>
      ${mod ? '<div class="row"><button class="b">Salva anamnesi</button></div>' : ''}</form>
    <div class="row"><a class="b o" href="#/anam/${id}">Scheda anamnestica completa</a></div>
    <h3>Note cliniche</h3>
    ${mod ? `<form id="fn">${area('Nuova nota', 'testo')}<div class="row"><button class="b" id="addn" disabled style="flex:1">Aggiungi nota</button><a class="b o" id="relb" style="flex:1" href="#/rel/new/${id}">Relazioni Clinica</a></div></form>` : ''}
    ${note.length ? note.map(n => `<div class="card"><div class="m">${esc(fDataOra(n.creato_il))} · ${esc(n.autore_nome)}</div>
      <div>${esc(n.testo).replace(/\n/g, '<br>')}</div>
      ${can('eliminazione', true) ? `<button class="t d" data-del="${n.id}">Elimina</button>` : ''}</div>`).join('') : '<p class="m">Nessuna nota</p>'}
    <h3>Relazioni cliniche</h3>
    ${rels.length ? rels.map(r => `<a class="card rl" href="#/rel/${r.id}/${id}"><b>Relazione ${esc((r.tipo || '').toLowerCase())}</b><div class="m">${esc(fData(r.data_relazione))}${r.medico ? ' · ' + esc(r.medico) : ''}${r.diagnosi ? ' · ' + esc(r.diagnosi.split('\n')[0].slice(0, 40)) : ''}</div></a>`).join('') : '<p class="m">Nessuna relazione</p>'}`;
  micro($('#tc'));
  if (mod) {
    $('#fa').onsubmit = e => {
      e.preventDefault(); const d = fobj(e.target);
      ok(async () => {
        await q(sb.from('anamnesi').upsert({ paziente_id: id, diagnosi: d.diagnosi.trim(), tipo_intervento: d.tipo_intervento.trim(), allergie: d.allergie.trim(), farmaci: d.farmaci.trim(), patologie: d.patologie.trim(), fumatore: d.fumatore || '' }, { onConflict: 'paziente_id' }));
        log('modifica_anamnesi', id); avviso('Fatto', 'Anamnesi salvata.');
      });
    };
    const ta = $('#fn textarea');
    ta.oninput = () => { $('#addn').disabled = !ta.value.trim(); };
    $('#fn').onsubmit = e => {
      e.preventDefault();
      ok(async () => {
        await q(sb.from('note_cliniche').insert({ paziente_id: id, testo: ta.value.trim(), autore_nome: me.nome || me.username }));
        log('nuova_nota', id); await tabClinica(pz);
      });
    };
  }
  document.querySelectorAll('[data-del]').forEach(b => b.onclick = () =>
    conferma('Eliminare la nota?', 'L\'operazione non si può annullare.', () => ok(async () => {
      await q(sb.from('note_cliniche').delete().eq('id', b.dataset.del)); await tabClinica(pz);
    })));
}

/* ---------- RELAZIONI CLINICHE ---------- */
const REL_TIPI = ['Pre-operatoria', 'Post-operatoria', 'Di controllo', 'Altro'];
const REL_MEDICI = ['Prof. Gabriele Delia', 'Dott. Pietro Micieli'];
const haMed = (txt, m) => String(txt || '').includes(m.split(' ').pop());
function relHtml(pz, r) {
  const tt = { 'Pre-operatoria': ' PRE-OPERATORIA', 'Post-operatoria': ' POST-OPERATORIA', 'Di controllo': ' DI CONTROLLO' }[r.tipo] || '';
  const sez = (t, v) => v && String(v).trim() ? `<h3>${t}</h3><p>${esc(v).replace(/\n/g, '<br>')}</p>` : '';
  return `<div class="rel"><div class="hd"><img src="${LOGO}" alt=""><h1>PROAESTHETICS</h1><p>STUDIO PROAESTHETICS CHIRURGIA PLASTICA ED ESTETICA</p></div>
    <h2>RELAZIONE CLINICA${tt}</h2>
    <div class="meta"><div><b>Paziente:</b> ${esc(pz.cognome)} ${esc(pz.nome)}<br>${pz.data_nascita ? `<b>Nato/a il:</b> ${esc(fData(pz.data_nascita))}<br>` : ''}${pz.codice_fiscale ? `<b>Cod. fiscale:</b> ${esc(pz.codice_fiscale)}` : ''}</div>
    <div style="text-align:right"><b>Data:</b> ${esc(fData(r.data_relazione))}<br>${r.medico ? `<b>Medico:</b> ${esc(r.medico)}` : ''}</div></div>
    ${sez('Motivo della visita / Anamnesi', r.motivo)}${sez('Esame obiettivo', r.esame)}${sez('Diagnosi', r.diagnosi)}${sez('Intervento / trattamento proposto', r.intervento)}${sez('Decorso e conclusioni', r.conclusioni)}
    <div class="fir"><div>Messina, ${esc(fData(r.data_relazione))}</div><div class="s">Firma e timbro del medico</div></div>
    <div class="ft">STUDIO PROAESTHETICS CHIRURGIA PLASTICA ED ESTETICA</div></div>`;
}
async function stampaRel(pz, r) {
  const p = $('#print'); p.innerHTML = relHtml(pz, r);
  await Promise.all([...p.querySelectorAll('img')].map(i => i.complete ? 0 : new Promise(x => { i.onload = i.onerror = x; })));
  const t = document.title; document.title = `Relazione ${pz.cognome} ${pz.nome}`;
  window.print();
  setTimeout(() => { document.title = t; p.innerHTML = ''; }, 1500);
}
VISTE.rel = async (id, pazId) => {
  const nuovo = id === 'new', mod = can('clinica', true);
  let r = nuovo ? null : (await q(sb.from('relazioni').select('*').eq('id', id))).find(x => x.id === id);
  if (!nuovo && !r) return schermo({ titolo: 'Relazione', back: true, body: '<p>Relazione non trovata</p>' });
  const pid = nuovo ? pazId : r.paziente_id;
  const pz = S.pazienti.find(x => x.id === pid);
  if (!pz) return schermo({ titolo: 'Relazione', back: true, body: '<p>Paziente non trovato</p>' });
  if (nuovo) {
    const an = (await q(sb.from('anamnesi').select('*').eq('paziente_id', pid)))[0] || {};
    r = { data_relazione: oggiISO(), tipo: 'Pre-operatoria', medico: REL_MEDICI.find(m => haMed(pz.medici, m)) || '', motivo: '', esame: '', diagnosi: an.diagnosi || '', intervento: an.tipo_intervento || '', conclusioni: '' };
  }
  schermo({
    titolo: nuovo ? 'Nuova relazione' : 'Relazione', back: true,
    body: `<p class="m" style="margin:6px 0 0">${esc(pz.cognome)} ${esc(pz.nome)}${pz.data_nascita ? ' · nato/a il ' + esc(fData(pz.data_nascita)) : ''}</p>
    <form id="f"><fieldset style="border:0;padding:0;margin:0" ${mod ? '' : 'disabled'}>
      <div class="grid2">${campo('Data', 'data_relazione', r.data_relazione, 'date', 'required')}
      <label class="f">Medico<select name="medico"><option value="">—</option>${REL_MEDICI.map(m => `<option ${m === r.medico ? 'selected' : ''}>${m}</option>`).join('')}</select></label></div>
      <label class="f">Tipo di relazione${scelta('tipo', REL_TIPI, r.tipo)}</label>
      ${area('Motivo della visita / Anamnesi', 'motivo', r.motivo)}${area('Esame obiettivo', 'esame', r.esame)}${area('Diagnosi', 'diagnosi', r.diagnosi)}
      ${area('Intervento / trattamento proposto', 'intervento', r.intervento)}${area('Decorso e conclusioni', 'conclusioni', r.conclusioni)}</fieldset>
      <div class="row">${mod ? '<button class="b">Salva relazione</button>' : ''}<button type="button" class="b o" id="pdfr">PDF / Stampa</button>
      ${!nuovo && can('eliminazione', true) ? '<button type="button" class="b d" id="del">Elimina relazione</button>' : ''}</div></form>`
  });
  document.querySelectorAll('#f textarea').forEach(t => { t.style.minHeight = '110px'; });
  micro($('#f'));
  const leggi = () => { const d = fobj($('#f')); return { data_relazione: d.data_relazione, medico: d.medico || '', tipo: d.tipo || 'Altro', motivo: (d.motivo || '').trim(), esame: (d.esame || '').trim(), diagnosi: (d.diagnosi || '').trim(), intervento: (d.intervento || '').trim(), conclusioni: (d.conclusioni || '').trim() }; };
  $('#pdfr').onclick = () => stampaRel(pz, leggi());
  $('#f').onsubmit = e => {
    e.preventDefault();
    ok(async () => {
      const rec = leggi();
      if (nuovo) await q(sb.from('relazioni').insert({ ...rec, paziente_id: pid, autore_nome: me.nome || me.username }));
      else await q(sb.from('relazioni').update(rec).eq('id', id));
      log(nuovo ? 'nuova_relazione' : 'modifica_relazione', pid); indietro();
    });
  };
  const del = $('#del');
  if (del) del.onclick = () => conferma('Eliminare la relazione?', 'L\'operazione non si può annullare.', () => ok(async () => {
    await q(sb.from('relazioni').delete().eq('id', id)); log('elimina_relazione', pid); indietro();
  }));
};

/* ---------- FOTO ---------- */
function preparaJpeg(file) {
  return new Promise((res, rej) => {
    const url = URL.createObjectURL(file), img = new Image();
    img.onload = () => {
      const f = Math.min(1, 1600 / Math.max(img.naturalWidth, img.naturalHeight));
      const c = document.createElement('canvas');
      c.width = Math.round(img.naturalWidth * f); c.height = Math.round(img.naturalHeight * f);
      c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
      URL.revokeObjectURL(url);
      c.toBlob(b => b ? res(b) : rej(new Error('Immagine non leggibile')), 'image/jpeg', 0.85);
    };
    img.onerror = () => { URL.revokeObjectURL(url); rej(new Error('Immagine non leggibile')); };
    img.src = url;
  });
}
async function urlFoto(foto) {
  if (!foto.length) return {};
  const { data, error } = await sb.storage.from('foto-pazienti').createSignedUrls(foto.map(f => f.percorso), 3600);
  if (error) throw new Error(error.message);
  const m = {}; (data || []).forEach(x => { if (x.signedUrl) m[x.path] = x.signedUrl; });
  return m;
}
async function tabFoto(pz) {
  const id = pz.id, mod = can('foto', true);
  const foto = await q(sb.from('foto').select('*').eq('paziente_id', id).order('creato_il', { ascending: false }));
  const urls = await urlFoto(foto);
  $('#tc').innerHTML = `${mod ? `<h3 style="margin-top:0">Nuova foto</h3>${scelta('etichetta', ['Prima', 'Dopo', 'Controllo'], 'Prima')}
    <div class="row"><label class="b" for="cam">Scatta / Galleria</label></div>
    <input type="file" id="cam" accept="image/*" hidden>` : ''}
    <div id="cmp"></div>
    ${foto.length ? '' : '<p class="m">Nessuna foto</p>'}
    <div class="grid2" style="margin-top:12px">${foto.map(f => `<div class="ph"><img src="${esc(urls[f.percorso] || '')}" data-big="${esc(urls[f.percorso] || '')}" alt="${esc(f.etichetta)}">
      <b>${esc(f.etichetta)}</b><br><span class="m">${esc(fDataOra(f.creato_il))}</span>
      <label class="chk"><input type="checkbox" data-sel="${f.id}">Confronta</label>
      ${can('eliminazione', true) ? `<button class="t d" data-del="${f.id}">Elimina</button>` : ''}</div>`).join('')}</div>`;
  if (mod) {
    $('#cam').onchange = e => {
      const file = e.target.files[0]; if (!file) return;
      const et = ($('#tc input[name=etichetta]:checked') || {}).value || 'Prima';
      ok(async () => {
        const blob = await preparaJpeg(file);
        const percorso = `${id}/${crypto.randomUUID()}.jpg`;
        const { error } = await sb.storage.from('foto-pazienti').upload(percorso, blob, { contentType: 'image/jpeg' });
        if (error) throw new Error(error.message);
        await q(sb.from('foto').insert({ paziente_id: id, percorso, etichetta: et }));
        log('carica_foto', id); await tabFoto(pz);
      });
    };
  }
  document.querySelectorAll('[data-big]').forEach(i => i.onclick = () => {
    if (!i.dataset.big) return;
    modal(`<img src="${esc(i.dataset.big)}" alt=""><div class="row"><button class="b" id="mk">Chiudi</button></div>`, true);
    $('#mk').onclick = chiudi;
  });
  const sel = [];
  document.querySelectorAll('[data-sel]').forEach(c => c.onchange = () => {
    if (c.checked) { sel.push(c); if (sel.length > 2) { sel.shift().checked = false; } }
    else sel.splice(sel.indexOf(c), 1);
    const g = $('#cmp');
    if (sel.length === 2) {
      g.innerHTML = '<div class="row"><button class="b" id="cf" style="width:100%">Confronta le 2 foto selezionate</button></div>';
      $('#cf').onclick = () => {
        const u = sel.map(s => urls[(foto.find(f => f.id === s.dataset.sel) || {}).percorso]);
        modal(`<div class="grid2"><img src="${esc(u[0])}" alt=""><img src="${esc(u[1])}" alt=""></div><div class="row"><button class="b" id="mk">Chiudi</button></div>`, true);
        $('#mk').onclick = chiudi;
      };
    } else g.innerHTML = '';
  });
  document.querySelectorAll('[data-del]').forEach(b => b.onclick = () =>
    conferma('Eliminare la foto?', 'L\'operazione non si può annullare.', () => ok(async () => {
      const f = foto.find(x => x.id === b.dataset.del);
      await sb.storage.from('foto-pazienti').remove([f.percorso]);
      await q(sb.from('foto').delete().eq('id', f.id));
      log('elimina_foto', id); await tabFoto(pz);
    })));
}

/* ---------- CONTI ---------- */
const totPrev = p => (p.voci || []).reduce((s, v) => s + (+v.prezzo || 0) * (+v.qta || 1), 0) - (+p.sconto || 0);
async function tabConti(pz) {
  const id = pz.id, mod = can('conti', true);
  const [prev, pag] = await Promise.all([
    q(sb.from('preventivi').select('*').eq('paziente_id', id).order('creato_il', { ascending: false })),
    q(sb.from('pagamenti').select('*').eq('paziente_id', id).order('creato_il', { ascending: false }))
  ]);
  const acc = prev.filter(p => p.stato === 'Accettato').reduce((s, p) => s + totPrev(p), 0);
  const pagato = pag.reduce((s, p) => s + (+p.importo || 0), 0);
  $('#tc').innerHTML = `<div class="sum"><div class="lb">Residuo</div><div class="big">${euro(acc - pagato)}</div><div class="sm">Accettato ${euro(acc)} · Pagato ${euro(pagato)}</div><div class="bar"><i style="width:${acc > 0 ? Math.min(100, Math.max(0, pagato / acc * 100)) : 0}%"></i></div></div>
    <h3>Preventivi</h3>${mod ? `<a class="b o" href="#/prev/${id}/new">Nuovo preventivo</a>` : ''}
    ${prev.length ? prev.map(p => `<a class="card" style="display:block;color:inherit;text-decoration:none" href="#/prev/${id}/${p.id}">
      <div class="m">${esc(fData(p.creato_il))} · ${esc(p.stato)}</div><b>${euro(totPrev(p))}</b><div>${esc((p.voci || []).map(v => v.nome).join(', '))}</div></a>`).join('') : '<p class="m">Nessun preventivo</p>'}
    <h3>Pagamenti</h3>
    ${mod ? `<form id="fp">${campo('Importo (€)', 'importo', '', 'text', 'inputmode="decimal" required')}
      ${campo('Data del pagamento', 'data', oggiISO(), 'date', 'required')}
      <label class="f">Metodo${scelta('metodo', ['Contanti', 'Carta', 'Bonifico', 'Altro'], 'Contanti')}</label>${campo('Nota', 'nota')}
      <div class="row"><button class="b">Registra pagamento</button></div></form>` : ''}
    ${pag.length ? pag.map(p => `<div class="kv"><span><span class="m">${esc(fData(p.creato_il))} · ${esc(p.metodo)}</span><br>${euro(p.importo)}${p.nota ? `<br><small class="m">${esc(p.nota)}</small>` : ''}</span>
      ${can('eliminazione', true) ? `<button class="t d" data-del="${p.id}">Elimina</button>` : ''}</div>`).join('') : '<p class="m">Nessun pagamento</p>'}`;
  if (mod) $('#fp').onsubmit = e => {
    e.preventDefault(); const d = fobj(e.target), v = num(d.importo);
    if (v <= 0) return avviso('Attenzione', 'Inserisci un importo maggiore di zero.');
    ok(async () => {
      await q(sb.from('pagamenti').insert({ paziente_id: id, importo: v, metodo: d.metodo || 'Contanti', nota: (d.nota || '').trim(), creato_il: new Date(`${d.data || oggiISO()}T12:00:00`).toISOString() }));
      log('pagamento', id); await tabConti(pz);
    });
  };
  document.querySelectorAll('[data-del]').forEach(b => b.onclick = () =>
    conferma('Eliminare il pagamento?', 'L\'operazione non si può annullare.', () => ok(async () => {
      await q(sb.from('pagamenti').delete().eq('id', b.dataset.del)); await tabConti(pz);
    })));
}

VISTE.prev = async (pazId, id) => {
  const nuovo = id === 'new';
  let ex = null;
  if (!nuovo) ex = await q(sb.from('preventivi').select('*').eq('id', id).maybeSingle());
  const P = { voci: (ex?.voci || []).map(v => ({ nome: v.nome, prezzo: String(v.prezzo), qta: String(v.qta) })), sconto: ex && +ex.sconto ? String(ex.sconto) : '', stato: ex?.stato || 'Bozza' };
  const mod = can('conti', true);
  schermo({
    titolo: nuovo ? 'Nuovo preventivo' : 'Preventivo', back: true,
    body: `${mod ? `<label class="f">Aggiungi dal listino<select id="dl"><option value="">Scegli…</option>
      ${S.listino.filter(l => l.attivo).map(l => `<option value="${l.id}">${esc(l.nome)} · ${euro(l.prezzo)}</option>`).join('')}<option value="libera">Voce libera</option></select></label>` : ''}
      <div id="voci"></div>${campo('Sconto €', 'sconto', P.sconto, 'text', 'id="sc" inputmode="decimal"')}
      <label class="f">Stato${scelta('stato', ['Bozza', 'Accettato', 'Rifiutato'], P.stato)}</label>
      <h3 id="tot"></h3><div class="row"><button class="b" id="sv">Salva</button><button class="b o" id="sh">Condividi</button></div>`
  });
  const voci = () => P.voci.filter(v => v.nome.trim()).map(v => ({ nome: v.nome.trim(), prezzo: num(v.prezzo), qta: Math.max(1, parseInt(v.qta) || 1) }));
  const totale = () => voci().reduce((s, v) => s + v.prezzo * v.qta, 0) - num($('#sc').value);
  const agg = () => { $('#tot').textContent = 'Totale: ' + euro(totale()); };
  const disegna = () => {
    $('#voci').innerHTML = P.voci.map((v, i) => `<div class="card"><label class="f" style="margin-top:0">Voce<input data-i="${i}" data-k="nome" value="${esc(v.nome)}"></label>
      <div class="grid2"><label class="f">Prezzo €<input data-i="${i}" data-k="prezzo" inputmode="decimal" value="${esc(v.prezzo)}"></label>
      <label class="f">Qtà<input data-i="${i}" data-k="qta" inputmode="numeric" value="${esc(v.qta)}"></label></div>
      <button class="t d" data-rm="${i}">Rimuovi voce</button></div>`).join('');
    document.querySelectorAll('#voci input').forEach(inp => inp.oninput = () => { P.voci[+inp.dataset.i][inp.dataset.k] = inp.value; agg(); });
    document.querySelectorAll('[data-rm]').forEach(b => b.onclick = () => { P.voci.splice(+b.dataset.rm, 1); disegna(); agg(); });
  };
  disegna(); agg();
  $('#sc').oninput = agg;
  if (mod) $('#dl').onchange = e => {
    const l = S.listino.find(x => x.id === e.target.value);
    P.voci.push(l ? { nome: l.nome, prezzo: String(l.prezzo), qta: '1' } : { nome: '', prezzo: '', qta: '1' });
    e.target.value = ''; disegna(); agg();
  };
  $('#sv').disabled = !mod;
  $('#sv').onclick = () => {
    const rec = { paziente_id: pazId, voci: voci(), sconto: num($('#sc').value), stato: ($('input[name=stato]:checked') || {}).value || 'Bozza' };
    if (!rec.voci.length) return avviso('Attenzione', 'Aggiungi almeno una voce.');
    ok(async () => {
      if (nuovo) await q(sb.from('preventivi').insert(rec)); else await q(sb.from('preventivi').update(rec).eq('id', id));
      log('preventivo', pazId); history.back();
    });
  };
  $('#sh').onclick = async () => {
    const v = voci(); if (!v.length) return;
    const sc = num($('#sc').value);
    const t = `Preventivo per ${nomePaz(pazId)}\n` + v.map(x => `- ${x.nome} x${x.qta}: ${euro(x.prezzo * x.qta)}`).join('\n') + (sc > 0 ? `\nSconto: ${euro(sc)}` : '') + `\nTotale: ${euro(totale())}`;
    try { if (navigator.share) await navigator.share({ text: t }); else { await navigator.clipboard.writeText(t); avviso('Copiato', 'Testo copiato negli appunti.'); } } catch (_) { /* annullato */ }
  };
};

/* ---------- AGENDA ---------- */
let agFiltro = 'Prossimi', agGiorno = null, agSett = 0;
const ICO_WA = '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="#D9B866" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 12a8 8 0 01-11.8 7L4 20l1.1-4A8 8 0 1120 12z"/></svg>';
const ICO_CAL = '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="#8A6417" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3.5" y="5" width="17" height="15" rx="2.5"/><path d="M3.5 10h17M8 3v4M16 3v4"/></svg>';
VISTE.agenda = async () => {
  schermo({
    titolo: 'Agenda', nav: 'agenda',
    body: `<div class="chips seg" id="flt">${['Oggi', 'Prossimi', 'Tutti'].map(o => `<label><input type="radio" name="f" value="${o}" ${!agGiorno && o === agFiltro ? 'checked' : ''}>${o}</label>`).join('')}</div>
      <div class="wk"><button type="button" class="wn" id="wp" aria-label="Settimana precedente">‹</button><div id="wkd" class="wkd"></div><button type="button" class="wn" id="wnx" aria-label="Settimana successiva">›</button></div>
      <p class="m" id="sub" style="margin:4px 0 10px"></p>
      <div class="list" id="lista"></div>${can('agenda', true) ? '<button class="fab" id="nuovo" aria-label="Nuovo appuntamento">+</button>' : ''}`
  });
  const GG = ['Dom', 'Lun', 'Mar', 'Mer', 'Gio', 'Ven', 'Sab'];
  const disegna = () => {
    const oggi = oggiISO();
    const lun = new Date(); lun.setHours(12, 0, 0, 0); lun.setDate(lun.getDate() - ((lun.getDay() + 6) % 7) + agSett * 7);
    const conta = {}; S.appuntamenti.forEach(x => { if (x.stato !== 'Annullato') { const k = isoData(new Date(x.inizio)); conta[k] = (conta[k] || 0) + 1; } });
    $('#wkd').innerHTML = [0, 1, 2, 3, 4, 5, 6].map(i => { const d = new Date(lun); d.setDate(lun.getDate() + i); const k = isoData(d);
      return `<button type="button" class="dy ${k === agGiorno ? 'on' : ''} ${k === oggi ? 'oggi' : ''}" data-d="${k}"><span>${GG[d.getDay()]}</span><b>${d.getDate()}</b><i class="${conta[k] ? 'p' : ''}"></i></button>`; }).join('');
    const l = S.appuntamenti.filter(a => {
      const d = isoData(new Date(a.inizio));
      if (agGiorno) return d === agGiorno;
      return agFiltro === 'Oggi' ? d === oggi : agFiltro === 'Prossimi' ? d >= oggi && a.stato !== 'Annullato' : true;
    });
    const etich = agGiorno ? new Date(agGiorno + 'T12:00:00').toLocaleDateString('it-IT', { weekday: 'long', day: 'numeric', month: 'long' }) : agFiltro === 'Oggi' ? 'Oggi' : agFiltro === 'Prossimi' ? 'Da oggi in poi' : 'Tutti gli appuntamenti';
    $('#sub').textContent = `${etich[0].toUpperCase() + etich.slice(1)} · ${l.length} appuntament${l.length === 1 ? 'o' : 'i'}`;
    $('#lista').innerHTML = l.length ? l.map(a => {
      const pz = S.pazienti.find(x => x.id === a.paziente_id) || {}, wa = waLink(a);
      const sub = [a.trattamento, pz.medici ? medicoBreve(pz.medici) : ''].filter(Boolean).join(' · ');
      const prog = a.stato === 'Programmato';
      return `<div class="it ag ${prog ? 'pr' : ''}"><span class="tm">${esc(new Date(a.inizio).toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' }))}<small>${esc(new Date(a.inizio).toLocaleDateString('it-IT', { day: '2-digit', month: '2-digit' }))}</small></span>
      <span class="g"><a class="gm" href="#/app/${a.id}"><span class="over">${esc(a.tipo || '')} · ${a.durata_min} min</span><span class="st ${prog ? '' : 'x'}">${esc(a.stato)}</span><br><b>${esc(nomePaz(a.paziente_id))}</b><br><small>${esc(sub)}</small></a>
      ${prog ? `<span class="ab">${wa ? `<a class="b" target="_blank" rel="noopener" href="${esc(wa)}">${ICO_WA}Promemoria</a>` : ''}<a class="b o" target="_blank" rel="noopener" href="${esc(gcalLink(a))}">${ICO_CAL}Calendario</a></span>` : ''}</span></div>`;
    }).join('') : '<p class="m">Nessun appuntamento</p>';
  };
  document.querySelectorAll('#flt input').forEach(i => i.onchange = () => { agFiltro = i.value; agGiorno = null; if (i.value === 'Oggi') agSett = 0; disegna(); });
  $('#wkd').onclick = e => { const b = e.target.closest('.dy'); if (!b) return; agGiorno = agGiorno === b.dataset.d ? null : b.dataset.d; document.querySelectorAll('#flt input').forEach(i => i.checked = !agGiorno && i.value === agFiltro); disegna(); };
  $('#wp').onclick = () => { agSett--; disegna(); };
  $('#wnx').onclick = () => { agSett++; disegna(); };
  disegna();
  if ($('#nuovo')) $('#nuovo').onclick = () => go('#/app/new');
};

/* ---------- CALENDARIO ---------- */
const iniziali = id => nomePaz(id).split(/\s+/).filter(Boolean).map(x => x[0].toUpperCase() + '.').join('');
const utcStamp = d => new Date(d).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
const nomeCogn = id => { const p = S.pazienti.find(x => x.id === id); return p ? `${p.nome} ${p.cognome}`.trim() : ''; };
function datiCal(a) {
  const fine = new Date(new Date(a.inizio).getTime() + (a.durata_min || 30) * 60000);
  return {
    titolo: [nomeCogn(a.paziente_id), a.tipo || 'Appuntamento', a.trattamento].filter(Boolean).join(' - '),
    note: a.note || '',
    inizio: utcStamp(a.inizio), fine: utcStamp(fine)
  };
}
function gcalLink(a) {
  const c = datiCal(a);
  return 'https://calendar.google.com/calendar/render?action=TEMPLATE&text=' + encodeURIComponent(c.titolo) +
    '&dates=' + c.inizio + '/' + c.fine + '&details=' + encodeURIComponent(c.note);
}
function waLink(a) {
  const pz = S.pazienti.find(x => x.id === a.paziente_id) || {};
  let n = String(pz.telefono || '').replace(/[^\d+]/g, '');
  if (n.startsWith('00')) n = n.slice(2); else if (n.startsWith('+')) n = n.slice(1); else if (n) n = '39' + n.replace(/^0+(?=3)/, '');
  const d = new Date(a.inizio);
  const saluto = new Date().getHours() < 17 ? 'Buongiorno' : 'Buonasera';
  if (a.stato === 'Eseguito') return '';
  const dt = d.toLocaleDateString('it-IT'), hh = d.toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' });
  const firma = '\n\nSTUDIO PROAESTHETICS CHIRURGIA PLASTICA ED ESTETICA';
  const testo = a.stato === 'Annullato'
    ? `${saluto} ${pz.nome || ''}, ci dispiace informarla che l'appuntamento del ${dt} alle ${hh} è stato annullato.\n\nLa ricontatteremo al più presto per comunicarle la prima data utile.${firma}`
    : `${saluto} ${pz.nome || ''}, le confermiamo l'appuntamento del ${dt} alle ${hh}.${firma}`;
  return n ? `https://wa.me/${n}?text=${encodeURIComponent(testo)}` : '';
}
function scaricaIcs(a) {
  const c = datiCal(a), esc2 = t => String(t).replace(/\\/g, '\\\\').replace(/\n/g, '\\n').replace(/[,;]/g, m => '\\' + m);
  const ics = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Clinica//IT', 'BEGIN:VEVENT', `UID:${a.id}@clinica`,
    `DTSTAMP:${utcStamp(new Date())}`, `DTSTART:${c.inizio}`, `DTEND:${c.fine}`, `SUMMARY:${esc2(c.titolo)}`,
    `DESCRIPTION:${esc2(c.note)}`, 'END:VEVENT', 'END:VCALENDAR'].join('\r\n');
  const url = URL.createObjectURL(new Blob([ics], { type: 'text/calendar' }));
  const l = document.createElement('a'); l.href = url; l.download = 'appuntamento.ics'; document.body.appendChild(l); l.click(); l.remove();
  setTimeout(() => URL.revokeObjectURL(url), 5000);
}

let salvato = '';
